// Local synthetic entry only. Never imported by the production Worker.
import {issueSession} from '../../server/auth-shared.mjs';
import {emptyState,transition} from '../../src/lib/model.mjs';
import {backupOf} from '../../src/lib/storage.mjs';
const page=`<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>学习中心 · 本地预览</title><style>body{background:#101319;color:#eff4fb;font:17px/1.8 system-ui;margin:0}main{max-width:760px;margin:8vh auto;padding:28px}h1{font-size:34px;line-height:1.3}p{color:#c0ccdd}.card{background:#242d3a;padding:25px;border:1px solid #63758d;border-radius:18px;margin:22px 0}button{font:600 16px system-ui;color:#142a24;background:#b3f0d6;border:0;border-radius:12px;padding:14px 24px;cursor:pointer}button:focus-visible,a:focus-visible{outline:3px solid #94c7ff;outline-offset:5px}a{color:#a6ccff}small{display:block;color:#c0ccdd;margin-top:12px}</style></head><body><main><p>STUDYTIMELY · 本地测试</p><h1>学习中心功能预览</h1><p>这里使用隔离的虚构账号，不需要 Google 登录，也不会连接正式账号或上传真实用户数据。</p><section class="card"><h2>打开功能预览</h2><p>准备了 2 个示例任务、0 条学习时长。进入后先查看学习概览。页面下方的「Manage sync &amp; recovery」可打开同步设置；确认启用后可读取云端示例并试用恢复功能。所有数据都保存在本机测试数据库。</p><form method="post"><input type="hidden" name="role" value="owner"><button>进入学习中心</button></form><small>同步不会在登录时自动开启，仍需在页面上确认。</small></section><section class="card"><h2>检查账号隔离</h2><p>第二个测试账号有独立的工作区。切换后，第一个账号的任务与待上传记录会留在原账号。</p><form method="post"><input type="hidden" name="role" value="learner"><button>切换到另一个测试账号</button></form></section><a href="/account">返回当前学习中心</a></main></body></html>`;
export async function syncPreview(request,env){
 const url=new URL(request.url);if(request.method==='GET')return new Response(page,{headers:{'Content-Type':'text/html;charset=utf-8','Cache-Control':'no-store','X-Robots-Tag':'noindex,nofollow'}});
 if(request.method!=='POST'||request.headers.get('origin')!==url.origin)return new Response('Forbidden',{status:403});
 const role=(await request.formData()).get('role');if(!['owner','learner','qa'].includes(role))return new Response('Invalid synthetic account',{status:400});
 const email='sync-'+role+'@studytimely.invalid',at=Date.now();await env.DB.prepare('INSERT INTO accounts(id,email,google_sub,created_at) VALUES(?,?,?,?) ON CONFLICT(email) DO NOTHING').bind(crypto.randomUUID(),email,'synthetic-sync:'+role,at).run();const account=await env.DB.prepare('SELECT id FROM accounts WHERE email=?').bind(email).first();
 let state=emptyState('synthetic-sync');state=transition(state,{type:'task-save',epoch:state.epoch,title:role==='learner'?'Plan my reading':'Review algebra',subject:'Maths',estimateMinutes:30},{id:'example-task-1',owner:'fixture',now:at}).state;
 state=transition(state,{type:'task-save',epoch:state.epoch,title:'Prepare tomorrow’s notes',subject:'English',estimateMinutes:20},{id:'example-task-2',owner:'fixture',now:at+1}).state;
 await env.DB.prepare('INSERT INTO workspaces(account_id,version,document,updated_at) VALUES(?,1,?,?) ON CONFLICT(account_id) DO NOTHING').bind(account.id,JSON.stringify(backupOf(state)),at).run();
 const session=await issueSession(request,env,account);return new Response(null,{status:303,headers:{Location:'/account','Set-Cookie':session.cookie,'Cache-Control':'no-store'}});
}
